    action character varying(100),
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_approver_type_valid CHECK (((approver_type)::text = ANY (ARRAY[('user'::character varying)::text, ('next_level'::character varying)::text, ('next_branch'::character varying)::text]))),
    CONSTRAINT chk_condition_order_positive CHECK ((condition_order >= 0)),
    CONSTRAINT chk_operator_valid CHECK (((operator)::text = ANY (ARRAY[('equals'::character varying)::text, ('not_equals'::character varying)::text, ('contains'::character varying)::text, ('not_contains'::character varying)::text, ('greater_than'::character varying)::text, ('less_than'::character varying)::text, ('in'::character varying)::text, ('not_in'::character varying)::text, ('starts_with'::character varying)::text, ('ends_with'::character varying)::text, ('is_null'::character varying)::text, ('is_not_null'::character varying)::text])))
);


