COPY public.cli_skills (id, name, title, description, parameters, queries, output_format, scope, is_active, created_by, created_at, updated_at) FROM stdin;
1	sales_activity_report	销售行动力分析	统计指定时段内各销售人员的新建项目数、报价总额和行动记录数,综合评估销售团队活跃度。	[{"name": "period", "type": "period", "required": true, "description": "统计周期(this_week/last_week/this_month/last_month/this_quarter/last_quarter)", "default_value": "last_week"}]	[{"sql": "SELECT u.real_name AS 销售人员, COUNT(p.id) AS 新建项目数 FROM projects p JOIN users u ON p.created_by = u.id WHERE p.is_deleted = FALSE AND p.created_at >= {period_start}::date AND p.created_at < ({period_end}::date + INTERVAL '1 day') GROUP BY u.real_name ORDER BY COUNT(p.id) DESC", "as_name": "projects", "description": "统计周期内各销售新建项目数"}, {"sql": "SELECT u.real_name AS 销售人员, q.currency AS 货币, COUNT(q.id) AS 报价数, COALESCE(SUM(q.amount), 0) AS 报价总额 FROM quotations q JOIN users u ON q.owner_id = u.id WHERE q.created_at >= {period_start}::date AND q.created_at < ({period_end}::date + INTERVAL '1 day') GROUP BY u.real_name, q.currency ORDER BY SUM(q.amount) DESC NULLS LAST", "as_name": "quotations", "description": "统计周期内各销售报价总额"}, {"sql": "SELECT u.real_name AS 销售人员, COUNT(a.id) AS 行动记录数 FROM actions a JOIN users u ON a.owner_id = u.id WHERE a.date >= {period_start}::date AND a.date <= {period_end}::date GROUP BY u.real_name ORDER BY COUNT(a.id) DESC", "as_name": "actions", "description": "统计周期内各销售行动记录数"}]	## 📊 销售行动力分析 ({period_start} ~ {period_end})\n\n### 新建项目\n{projects.table}\n\n### 报价情况\n{quotations.table}\n\n### 行动记录\n{actions.table}	global	t	\N	2026-04-06 14:26:26.180065	2026-04-06 14:26:26.180069
2	customer_overview	客户全景	根据客户名称关键词,查询客户基本信息、联系人、关联项目和报价汇总,提供 360 度客户视图。	[{"name": "keyword", "type": "string", "required": true, "description": "客户名称关键词"}]	[{"sql": "SELECT id, company_name AS 公司名称, company_type AS 类型, country AS 国家, industry AS 行业, status AS 状态 FROM companies WHERE company_name ILIKE '%' || {keyword} || '%' AND is_deleted = FALSE ORDER BY company_name LIMIT 10", "as_name": "company", "description": "查询匹配的客户公司信息"}, {"sql": "SELECT c.name AS 姓名, c.department AS 部门, c.position AS 职位, c.phone AS 电话, c.email AS 邮箱, co.company_name AS 所属公司 FROM contacts c JOIN companies co ON c.company_id = co.id WHERE co.company_name ILIKE '%' || {keyword} || '%' AND co.is_deleted = FALSE ORDER BY c.is_primary DESC, c.name", "as_name": "contacts", "description": "查询客户的联系人列表"}, {"sql": "SELECT p.project_name AS 项目名称, p.project_type AS 项目类型, p.current_stage AS 当前阶段, p.status AS 状态, p.end_user AS 终端用户 FROM projects p JOIN project_customer_associations pca ON pca.project_id = p.id JOIN companies co ON pca.company_id = co.id WHERE co.company_name ILIKE '%' || {keyword} || '%' AND co.is_deleted = FALSE AND p.is_deleted = FALSE ORDER BY p.created_at DESC", "as_name": "projects", "description": "查询客户关联的项目"}, {"sql": "SELECT q.currency AS 货币, COUNT(q.id) AS 报价数, COALESCE(SUM(q.amount), 0) AS 报价总额 FROM quotations q JOIN projects p ON q.project_id = p.id JOIN project_customer_associations pca ON pca.project_id = p.id JOIN companies co ON pca.company_id = co.id WHERE co.company_name ILIKE '%' || {keyword} || '%' AND co.is_deleted = FALSE AND p.is_deleted = FALSE GROUP BY q.currency ORDER BY SUM(q.amount) DESC NULLS LAST", "as_name": "quotations", "description": "汇总客户相关报价(通过项目关联)"}]	## 🏢 客户全景 — 关键词: {keyword}\n\n### 公司信息\n{if company}{company.table}{endif}{if !company}未找到匹配的客户公司。{endif}\n\n### 联系人\n{if contacts}{contacts.table}{endif}{if !contacts}暂无联系人记录。{endif}\n\n### 关联项目\n{if projects}{projects.table}{endif}{if !projects}暂无关联项目。{endif}\n\n### 报价汇总\n{if quotations}{quotations.table}{endif}{if !quotations}暂无报价记录。{endif}	global	t	\N	2026-04-06 14:26:26.186532	2026-04-06 14:26:26.18654
3	project_detail	项目详情	根据项目名称关键词,查看项目基本信息、报价列表、阶段变更历史和最近行动记录。	[{"name": "keyword", "type": "string", "required": true, "description": "项目名称关键词"}]	[{"sql": "SELECT p.id, p.project_name AS 项目名称, p.project_type AS 项目类型, p.current_stage AS 当前阶段, p.status AS 状态, p.end_user AS 终端用户, p.dealer AS 经销商, p.contractor AS 承包商, u.real_name AS 负责人 FROM projects p LEFT JOIN users u ON p.owner_id = u.id WHERE p.project_name ILIKE '%' || {keyword} || '%' AND p.is_deleted = FALSE ORDER BY p.created_at DESC LIMIT 5", "as_name": "project", "description": "查询匹配的项目基本信息"}, {"sql": "SELECT q.quotation_number AS 报价单号, q.amount AS 金额, q.currency AS 货币, q.approval_status AS 审批状态, u.real_name AS 报价人 FROM quotations q JOIN projects p ON q.project_id = p.id LEFT JOIN users u ON q.owner_id = u.id WHERE p.project_name ILIKE '%' || {keyword} || '%' AND p.is_deleted = FALSE ORDER BY q.created_at DESC", "as_name": "quotations", "description": "查询项目的报价列表"}, {"sql": "SELECT psh.from_stage AS 原阶段, psh.to_stage AS 新阶段, psh.change_date::date AS 变更日期, psh.remarks AS 备注 FROM project_stage_history psh JOIN projects p ON psh.project_id = p.id WHERE p.project_name ILIKE '%' || {keyword} || '%' AND p.is_deleted = FALSE ORDER BY psh.change_date DESC", "as_name": "stage_history", "description": "查询项目阶段变更记录"}, {"sql": "SELECT a.date AS 日期, a.communication AS 内容, u.real_name AS 记录人 FROM actions a JOIN projects p ON a.project_id = p.id LEFT JOIN users u ON a.owner_id = u.id WHERE p.project_name ILIKE '%' || {keyword} || '%' AND p.is_deleted = FALSE ORDER BY a.date DESC LIMIT 10", "as_name": "actions", "description": "查询项目最近的行动记录"}]	## 📋 项目详情 — 关键词: {keyword}\n\n### 项目信息\n{if project}{project.table}{endif}{if !project}未找到匹配的项目。{endif}\n\n### 报价列表\n{if quotations}{quotations.table}{endif}{if !quotations}暂无报价记录。{endif}\n\n### 阶段变更历史\n{if stage_history}{stage_history.table}{endif}{if !stage_history}暂无阶段变更记录。{endif}\n\n### 最近行动记录\n{if actions}{actions.table}{endif}{if !actions}暂无行动记录。{endif}	global	t	\N	2026-04-06 14:26:26.189513	2026-04-06 14:26:26.189515
4	pipeline_analysis	项目管线分析	按项目阶段汇总项目数和报价总额,呈现销售管线全貌。	[]	[{"sql": "SELECT p.current_stage AS 阶段, COUNT(DISTINCT p.id) AS 项目数, COALESCE(SUM(q.amount), 0) AS 报价总额 FROM projects p LEFT JOIN quotations q ON q.project_id = p.id WHERE p.is_deleted = FALSE AND p.status != 'lost' GROUP BY p.current_stage ORDER BY CASE p.current_stage   WHEN 'discover' THEN 1   WHEN 'embed' THEN 2   WHEN 'pre_tender' THEN 3   WHEN 'tendering' THEN 4   WHEN 'awarded' THEN 5   WHEN 'quoted' THEN 6   WHEN 'signed' THEN 7   WHEN 'lost' THEN 8   WHEN 'paused' THEN 9   ELSE 99 END", "as_name": "pipeline", "description": "按阶段汇总项目数和报价金额"}]	## 🔄 项目管线分析\n\n{pipeline.table}\n\n共 {pipeline.count} 个阶段有活跃项目。	global	t	\N	2026-04-06 14:26:26.191651	2026-04-06 14:26:26.191653
5	sales_weekly_review	销售人员周报分析	生成指定销售人员的周度工作分析报告。触发词：周报、周报分析、上周周报、weekly review、销售周报。包含行动记录明细、每日活动分布、项目管线状态和报价活动。	[{"name": "user_name", "type": "string", "required": true, "description": "销售人员姓名"}, {"name": "period", "type": "period", "required": true, "description": "统计周期", "default_value": "last_week"}]	[{"sql": "SELECT (SELECT COUNT(*) FROM actions a JOIN users u ON a.owner_id=u.id   WHERE u.real_name ILIKE '%' || {user_name} || '%'   AND a.date >= {period_start}::date AND a.date <= {period_end}::date) AS 行动记录数, (SELECT COUNT(DISTINCT a.date) FROM actions a JOIN users u ON a.owner_id=u.id   WHERE u.real_name ILIKE '%' || {user_name} || '%'   AND a.date >= {period_start}::date AND a.date <= {period_end}::date) AS 活跃天数, (SELECT COUNT(*) FROM quotations q JOIN users u ON q.owner_id=u.id   WHERE u.real_name ILIKE '%' || {user_name} || '%'   AND q.created_at >= {period_start}::date AND q.created_at < ({period_end}::date + INTERVAL '1 day')) AS 报价数, (SELECT COALESCE(SUM(q.amount),0) FROM quotations q JOIN users u ON q.owner_id=u.id   WHERE u.real_name ILIKE '%' || {user_name} || '%'   AND q.created_at >= {period_start}::date AND q.created_at < ({period_end}::date + INTERVAL '1 day')) AS 报价总额, (SELECT COUNT(*) FROM projects p JOIN users u ON p.owner_id=u.id   WHERE u.real_name ILIKE '%' || {user_name} || '%'   AND p.is_deleted=FALSE AND p.current_stage NOT IN ('lost','paused','signed')) AS 活跃项目数", "as_name": "summary", "description": "周度概览统计"}, {"sql": "SELECT a.date AS 日期, COALESCE(co.company_name, '-') AS 客户, COALESCE(p.project_name, '-') AS 项目, LEFT(a.communication, 150) AS 内容摘要 FROM actions a JOIN users u ON a.owner_id = u.id LEFT JOIN companies co ON a.company_id = co.id LEFT JOIN projects p ON a.project_id = p.id WHERE u.real_name ILIKE '%' || {user_name} || '%' AND a.date >= {period_start}::date AND a.date <= {period_end}::date ORDER BY a.date, a.id", "as_name": "actions", "description": "周期内行动记录明细"}, {"sql": "SELECT d.day::date AS 日期, COALESCE(ac.action_count, 0) AS 行动数, COALESCE(wi.item_count, 0) AS 工作项数, COALESCE(wl.log_status, '无') AS 日志状态, CASE WHEN COALESCE(ac.action_count,0)=0 AND COALESCE(wi.item_count,0)=0 THEN '空白'      WHEN COALESCE(ac.action_count,0)>0 THEN '活跃' ELSE '仅工作项' END AS 备注 FROM generate_series({period_start}::date, {period_end}::date, '1 day'::interval) d(day) LEFT JOIN (   SELECT a.date, COUNT(*) AS action_count   FROM actions a JOIN users u ON a.owner_id = u.id   WHERE u.real_name ILIKE '%' || {user_name} || '%'   GROUP BY a.date ) ac ON ac.date = d.day::date LEFT JOIN (   SELECT wi.planned_date, COUNT(*) AS item_count   FROM work_items wi JOIN users u ON wi.owner_id = u.id   WHERE u.real_name ILIKE '%' || {user_name} || '%'   GROUP BY wi.planned_date ) wi ON wi.planned_date = d.day::date LEFT JOIN (   SELECT wl.log_date, wl.status AS log_status   FROM worklogs wl JOIN users u ON wl.owner_id = u.id   WHERE u.real_name ILIKE '%' || {user_name} || '%' ) wl ON wl.log_date = d.day::date WHERE EXTRACT(DOW FROM d.day) NOT IN (0, 6) ORDER BY d.day", "as_name": "daily", "description": "每日行动分布+日志状态"}, {"sql": "SELECT p.project_name AS 项目, p.current_stage AS 阶段, p.status AS 状态, COALESCE(ac.action_count, 0) AS 本周行动数, CASE WHEN COALESCE(ac.action_count,0)=0 AND p.current_stage IN ('tendering','pre_tender','awarded')      THEN '⚠ 零行动'      WHEN COALESCE(ac.action_count,0)>0 THEN '✓ 有跟进'      ELSE '-' END AS 本周进展 FROM projects p JOIN users u ON p.owner_id = u.id LEFT JOIN (   SELECT a.project_id, COUNT(*) AS action_count   FROM actions a   WHERE a.date >= {period_start}::date AND a.date <= {period_end}::date   GROUP BY a.project_id ) ac ON ac.project_id = p.id WHERE u.real_name ILIKE '%' || {user_name} || '%' AND p.is_deleted = FALSE AND p.current_stage NOT IN ('lost', 'paused', 'signed') AND (COALESCE(ac.action_count,0) > 0      OR p.current_stage IN ('tendering','pre_tender','awarded')) ORDER BY CASE p.current_stage   WHEN 'awarded' THEN 1 WHEN 'tendering' THEN 2   WHEN 'pre_tender' THEN 3 WHEN 'embed' THEN 4   WHEN 'discover' THEN 5 ELSE 9 END, COALESCE(ac.action_count,0) DESC", "as_name": "pipeline", "description": "重点项目管线（有行动+风险项）"}, {"sql": "SELECT q.quotation_number AS 报价单号, COALESCE(p.project_name, '-') AS 项目, q.amount AS 金额, q.currency AS 货币, q.approval_status AS 状态 FROM quotations q JOIN users u ON q.owner_id = u.id LEFT JOIN projects p ON q.project_id = p.id WHERE u.real_name ILIKE '%' || {user_name} || '%' AND q.created_at >= {period_start}::date AND q.created_at < ({period_end}::date + INTERVAL '1 day') ORDER BY q.created_at DESC", "as_name": "quotations", "description": "周期内报价明细"}, {"sql": "SELECT COALESCE(pmd.metric_name, upt.item_code) AS 指标, upt.annual_target_override AS 年度目标, CASE EXTRACT(QUARTER FROM {period_end}::date)   WHEN 1 THEN upt.q1_target_override   WHEN 2 THEN upt.q2_target_override   WHEN 3 THEN upt.q3_target_override   WHEN 4 THEN upt.q4_target_override END AS 本季度目标 FROM user_performance_targets upt JOIN users u ON upt.user_id = u.id LEFT JOIN performance_metrics_definition pmd ON pmd.metric_code = upt.item_code WHERE u.real_name ILIKE '%' || {user_name} || '%' AND upt.year = EXTRACT(YEAR FROM {period_end}::date)::int ORDER BY upt.item_code", "as_name": "targets", "description": "被评估人的绩效目标"}, {"sql": "WITH quarter_range AS (   SELECT DATE_TRUNC('quarter', {period_end}::date)::date AS q_start,          (DATE_TRUNC('quarter', {period_end}::date) + INTERVAL '3 months' - INTERVAL '1 day')::date AS q_end ) SELECT COALESCE(pmd.metric_name, 'sales_target') AS 指标, ROUND((COALESCE(SUM(q.amount),0)/10000)::numeric, 2) AS 本季度累计, COALESCE(pmd.default_unit, '万元') AS 单位 FROM quotations q JOIN users u ON q.owner_id = u.id CROSS JOIN quarter_range qr LEFT JOIN performance_metrics_definition pmd ON pmd.metric_code = 'sales_target' WHERE u.real_name ILIKE '%' || {user_name} || '%' AND q.created_at >= qr.q_start AND q.created_at < qr.q_end + INTERVAL '1 day' GROUP BY pmd.metric_name, pmd.default_unit UNION ALL SELECT COALESCE(pmd2.metric_name, 'new_projects'), COUNT(*)::numeric, COALESCE(pmd2.default_unit, '个') FROM projects p JOIN users u ON p.created_by = u.id CROSS JOIN quarter_range qr LEFT JOIN performance_metrics_definition pmd2 ON pmd2.metric_code = 'new_projects' WHERE u.real_name ILIKE '%' || {user_name} || '%' AND p.is_deleted = FALSE AND p.created_at >= qr.q_start AND p.created_at < qr.q_end + INTERVAL '1 day' GROUP BY pmd2.metric_name, pmd2.default_unit UNION ALL SELECT COALESCE(pmd3.metric_name, 'new_customers'), COUNT(DISTINCT co.id)::numeric, COALESCE(pmd3.default_unit, '个') FROM companies co JOIN users u ON co.owner_id = u.id CROSS JOIN quarter_range qr LEFT JOIN performance_metrics_definition pmd3 ON pmd3.metric_code = 'new_customers' WHERE u.real_name ILIKE '%' || {user_name} || '%' AND co.is_deleted = FALSE AND co.created_at >= qr.q_start AND co.created_at < qr.q_end + INTERVAL '1 day' GROUP BY pmd3.metric_name, pmd3.default_unit", "as_name": "quarter_actual", "description": "本季度累计实际数据"}]	## {user_name} 销售周报 ({period_start} ~ {period_end})\n\n### 概览\n{summary.table}\n\n### 1. 行动记录明细 ({actions.count}条)\n{if actions}{actions.table}{endif}{if !actions}本周无行动记录。{endif}\n\n### 2. 每日活动分布\n{daily.table}\n\n### 3. 项目管线（重点项目）\n{if pipeline}{pipeline.table}{endif}{if !pipeline}暂无重点项目。{endif}\n\n### 4. 本周报价 ({quotations.count}份)\n{if quotations}{quotations.table}{endif}{if !quotations}本周无新报价。{endif}\n\n### 5. 绩效目标达成进度\n{if targets}**个人目标设定:**\n{targets.table}\n\n**本季度累计实际:**\n{quarter_actual.table}{endif}{if !targets}暂无绩效目标数据。{endif}\n\n---\n### 6. 分析与风险提示\n请基于以上数据，从以下维度给出简要分析（每条1-2句话）：\n- **活跃度评估**：本周行动天数/总工作日，是否有连续空白日\n- **项目风险**：招标中/标前/已中标阶段零行动的项目数量及风险\n- **报价进展**：报价数量和金额是否匹配季度目标节奏\n- **绩效差距**：本季度累计 vs 季度目标的达成率，哪些指标落后\n- **重点关注**：需要立即跟进的项目或客户\n	global	t	\N	2026-04-10 05:14:24.350549	2026-04-10 05:14:24.350554
