COPY public.meeting_minutes (id, recording_id, status, version, title, summary, key_points, decisions, participants, project_id, customer_id, generation_mode, owner_id, created_at, updated_at, published_at, is_deleted) FROM stdin;
\.


--
-- Data for Name: meeting_recordings; Type: TABLE DATA; Schema: public; Owner: pma
--

COPY public.meeting_recordings (id, title, description, recording_url, duration, recorded_at, project_id, company_id, created_by_id, created_at, updated_at, is_deleted, file_size_bytes, storage_url, status, duration_seconds, work_item_id, error_message, owner_id, meeting_time, uploaded_chunks, storage_path, recording_mode, chunk_paths, total_chunks) FROM stdin;
\.


--
-- Data for Name: meeting_speakers; Type: TABLE DATA; Schema: public; Owner: pma
--

COPY public.meeting_speakers (id, transcript_id, speaker_label, user_id, external_name, sample_text, sample_start_time, sample_end_time, total_duration_seconds, segment_count, created_at) FROM stdin;
\.


--
-- Data for Name: meeting_transcripts; Type: TABLE DATA; Schema: public; Owner: pma
--

COPY public.meeting_transcripts (id, recording_id, status, progress_percent, error_message, full_text, segments, language, speaker_count, speakers_mapped, created_at, updated_at, completed_at) FROM stdin;
\.


--
-- Data for Name: messages; Type: TABLE DATA; Schema: public; Owner: pma
--

COPY public.messages (id, message_type, sender_id, recipient_id, title, content, related_object_type, related_object_id, metadata, is_read, read_at, created_at) FROM stdin;
